import itertools
import random

def check_girth(edges, n, min_girth):
    """Check if graph has girth at least min_girth."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS to find shortest cycle through start
        visited = {start: (None, 0)}  # vertex -> (parent, distance)
        queue = [start]
        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            dist = visited[u][1]
            if dist >= min_girth:
                break
            for v in adj[u]:
                if v not in visited:
                    visited[v] = (u, dist + 1)
                    queue.append(v)
                elif v != visited[u][0]:
                    # Found a cycle
                    cycle_len = dist + visited[v][1] + 1
                    if cycle_len < min_girth:
                        return False
    return True

def check_colorable(edges, n, k):
    """Check if graph is k-colorable using backtracking."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in adj[v]:
                if neighbor < v and colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

