def bfs_shortest_path(adj, start, end, n):
    """Find shortest path from start to end in adj (excluding direct edge)."""
    visited = {start: 0}
    queue = deque([start])
    while queue:
        u = queue.popleft()
        dist = visited[u]
        if dist >= min_girth - 1:
            return min_girth  # Path too long, edge is safe
        for v in adj[u]:
            if v == end:
                return dist + 1
            if v not in visited:
                visited[v] = dist + 1
                queue.append(v)
    return min_girth  # No path found

def check_girth_fast(adj, n, min_girth):
    """Check girth by BFS from each vertex."""
    for start in range(n):
        visited = {start: (None, 0)}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            dist = visited[u][1]
            if dist >= min_girth:
                break
            for v in adj[u]:
                if v not in visited:
                    visited[v] = (u, dist + 1)
                    queue.append(v)
                elif v != visited[u][0]:
                    cycle_len = dist + visited[v][1] + 1
                    if cycle_len < min_girth:
                        return False
    return True

def is_k_colorable(adj, n, k):
    """Check k-colorability with backtracking and ordering."""
    # Order vertices by degree (most constrained first)
    degrees = [(len(adj[i]), i) for i in range(n)]
    degrees.sort(reverse=True)
    order = [i for _, i in degrees]

    colors = [-1] * n

    def backtrack(idx):
        if idx == n:
            return True
        v = order[idx]
        used = set()
        for neighbor in adj[v]:
            if colors[neighbor] != -1:
                used.add(colors[neighbor])
        for c in range(k):
            if c not in used:
                colors[v] = c
                if backtrack(idx + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

